// HelloServer - React Server Component
//
// This component runs ONLY on the server. No JavaScript for it is sent to the browser.
// It demonstrates key RSC capabilities:
//
// 1. Async data fetching — use await directly in the component (no useEffect needed)
// 2. Server-only code — access databases, file systems, or secrets safely
// 3. Zero client JS — heavy libraries used here don't increase your bundle size
// 4. Streaming — wrapped in <Suspense>, this component streams HTML as it resolves
//
// For more information, see:
// https://reactonrails.com/docs/pro/react-server-components/

import React from 'react';
import LikeButton from './LikeButton';

interface Metric {
  label: string;
  value: string;
}

interface FeaturedGuest {
  hometown: string;
  name: string;
  request: string;
}

interface HelloServerProps {
  featuredGuest: FeaturedGuest;
  generatedAt: string;
  highlights: string[];
  metrics: Metric[];
  title: string;
}

const HelloServer = async ({
  featuredGuest,
  generatedAt,
  highlights,
  metrics,
  title,
}: HelloServerProps) => {
  return (
    <div style={{ fontFamily: '"Avenir Next", Avenir, sans-serif', maxWidth: 720, margin: '0 auto' }}>
      <h2 style={{ fontSize: '2rem', marginBottom: 8 }}>{title}</h2>
      <p style={{ color: '#4d5b6a', fontSize: '0.95rem' }}>Generated in Rails at: {generatedAt}</p>

      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))',
          gap: 12,
          margin: '24px 0',
        }}
      >
        {metrics.map((metric) => (
          <div
            key=[REDACTED]
            style={{
              background: '#fffdf8',
              border: '1px solid rgba(17, 32, 49, 0.12)',
              borderRadius: 16,
              padding: 16,
            }}
          >
            <p style={{ margin: 0, color: '#4d5b6a', fontSize: '0.85rem', textTransform: 'uppercase' }}>
              {metric.label}
            </p>
            <p style={{ margin: '10px 0 0', fontSize: '1.4rem', fontWeight: 700 }}>{metric.value}</p>
          </div>
        ))}
      </div>

      <div
        style={{
          background: '#fff7ed',
          border: '1px solid #fed7aa',
          borderRadius: 18,
          padding: 16,
          margin: '16px 0',
        }}
      >
        <h3 style={{ margin: '0 0 12px' }}>Server-provided highlights</h3>
        <ul style={{ margin: 0, paddingLeft: 20 }}>
          {highlights.map((highlight) => (
            <li key=[REDACTED]
              {highlight}
            </li>
          ))}
        </ul>
      </div>

      <div
        style={{
          background: '#eef6ff',
          border: '1px solid #bfdbfe',
          borderRadius: 18,
          padding: 16,
          marginBottom: 20,
        }}
      >
        <h3 style={{ margin: '0 0 8px' }}>Featured guest request</h3>
        <p style={{ margin: 0, fontWeight: 700 }}>{featuredGuest.name}</p>
        <p style={{ margin: '4px 0', color: '#4d5b6a' }}>{featuredGuest.hometown}</p>
        <p style={{ margin: '8px 0 0' }}>{featuredGuest.request}</p>
      </div>

      <LikeButton />
    </div>
  );
};

export default HelloServer;

'use client';

// LikeButton - Client Component
//
// This component has the 'use client' directive, so its JavaScript IS sent to the browser.
// It demonstrates how client components work alongside server components:
//
// - Only this component's JS is included in the client bundle
// - The parent HelloServer component sends ZERO JS to the browser
// - React hydrates just this interactive island within the server-rendered HTML

import React, { useState } from 'react';

const LikeButton: React.FC = () => {
  const [likes, setLikes] = useState(0);

  return (
    <div
      style={{
        display: 'flex',
        alignItems: 'center',
        gap: 12,
        marginTop: 16,
        padding: '12px 16px',
        background: '#fefce8',
        border: '1px solid #fde68a',
        borderRadius: 8,
      }}
    >
      <button
        type="button"
        onClick={() => setLikes((prev) => prev + 1)}
        style={{
          padding: '8px 16px',
          fontSize: '1em',
          cursor: 'pointer',
          borderRadius: 6,
          border: '1px solid #d1d5db',
          background: '#fff',
        }}
      >
        👍 Like
      </button>
      <span>
        {likes} {likes === 1 ? 'like' : 'likes'}
      </span>
      <span style={{ color: '#92400e', fontSize: '0.85em' }}>
        ← This button is a client component (check your browser&apos;s Network tab — only its JS was sent)
      </span>
    </div>
  );
};

export default LikeButton;

// HelloServer Entry Point - Re-exports the server component for auto_load_bundle
// This file is discovered by React on Rails' auto_load_bundle feature
// and registered automatically in both client and server bundles.
//
// Note: No 'use client' directive here - this is a Server Component.
// The actual component in ../components/HelloServer.tsx runs only on the server.

import HelloServer from '../components/HelloServer';

export default HelloServer;

